/** Explicit, local-only counterpart of mcp-js's Supabase generator.
 * Uses a relative entry and resolves project aliases before npm externalization,
 * avoiding the SDK's Windows drive-path bug. Does not load env files, extract a
 * manifest, alter configuration, or deploy. Default mode only checks parity.
 */
import { readFile, writeFile } from "node:fs/promises";
import { createHash } from "node:crypto";
import { dirname, isAbsolute, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { build } from "esbuild";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const output = resolve(root, "supabase/functions/mcp/index.ts");
const banner =
  "// AUTO-GENERATED by @lovable.dev/mcp-js — do not edit. Regenerated by the Vite plugin.\n// To take ownership, delete this banner line; the plugin then leaves the file alone.\n// supabase function: mcp\n// Bundled from src/lib/mcp/index.ts by @lovable.dev/mcp-js.\n";

export async function generateMcpEdgeBundle() {
  const [pkg, manifest, sdk] = await Promise.all(
    [
      "package.json",
      ".lovable/mcp/manifest.json",
      "node_modules/@lovable.dev/mcp-js/package.json",
    ].map(async (p) => JSON.parse(await readFile(resolve(root, p), "utf8"))),
  );
  if (sdk.version !== manifest.sdk_version)
    throw new Error("MCP SDK version differs from the committed manifest.");
  const issuer = new URL(manifest.auth.issuer);
  if (
    issuer.protocol !== "https:" ||
    !/^[a-z0-9]+\.supabase\.co$/.test(issuer.hostname) ||
    issuer.pathname !== "/auth/v1"
  )
    throw new Error("Unexpected committed MCP issuer.");
  const projectRef = issuer.hostname.split(".")[0];
  const versions = { ...pkg.peerDependencies, ...pkg.devDependencies, ...pkg.dependencies };
  const result = await build({
    stdin: {
      contents:
        'import mcp from "./src/lib/mcp/index.ts";\nimport { createSupabaseHandler } from "@lovable.dev/mcp-js/stacks/supabase";\nDeno.serve(createSupabaseHandler(mcp, { functionName: "mcp" }));\n',
      resolveDir: root,
      sourcefile: "lovable-mcp-supabase-entry.ts",
      loader: "ts",
    },
    bundle: true,
    write: false,
    metafile: true,
    format: "esm",
    platform: "neutral",
    target: "esnext",
    absWorkingDir: root,
    logLevel: "silent",
    define: {
      "import.meta.env": JSON.stringify({ VITE_SUPABASE_PROJECT_ID: projectRef }),
      "import.meta.env.VITE_SUPABASE_PROJECT_ID": JSON.stringify(projectRef),
    },
    plugins: [
      {
        name: "portable-mcp-npm-imports",
        setup(b) {
          b.onResolve({ filter: /.*/ }, (args) => {
            const p = args.path;
            if (p.startsWith("@/"))
              return b.resolve("./src/" + p.slice(2), { resolveDir: root, kind: args.kind });
            if (p.startsWith(".") || isAbsolute(p)) return null;
            if (/^(npm|node|jsr|https?|data):/.test(p)) return { path: p, external: true };
            const name = p.startsWith("@") ? p.split("/").slice(0, 2).join("/") : p.split("/")[0];
            const range = name === "@lovable.dev/mcp-js" ? sdk.version : versions[name];
            if (typeof range !== "string" || !/^[\dv^~>=]|^latest$/.test(range))
              throw new Error("Unpinned MCP dependency: " + name);
            return { path: "npm:" + name + "@" + range + p.slice(name.length), external: true };
          });
        },
      },
    ],
  });
  const code = banner + result.outputFiles[0].text;
  if (/["'](?:npm:)?[A-Za-z]:[\\/]|(?:from\s+|import\s*)["']@\//.test(code))
    throw new Error("Nonportable MCP output.");
  return code;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const mode = process.argv[2] ?? "--check";
  if (!["--check", "--write"].includes(mode) || process.argv.length > 3)
    throw new Error("Usage: node scripts/sync-mcp-edge-bundle.mjs [--check|--write]");
  const existing = (await readFile(output, "utf8")).replace(/\r\n/g, "\n");
  if (!existing.startsWith(banner))
    throw new Error("Refusing to overwrite an unrecognized MCP bundle.");
  const code = await generateMcpEdgeBundle();
  if (mode === "--write" && existing !== code) await writeFile(output, code, "utf8");
  const equal = existing === code;
  console.log(
    JSON.stringify({
      mode,
      matchedBefore: equal,
      sha256: createHash("sha256").update(code).digest("hex"),
    }),
  );
  if (mode === "--check" && !equal) process.exitCode = 1;
}
